import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";var i=JSON.parse(`{"title":"Getting started","description":"","frontmatter":{},"headers":[],"relativePath":"guide/getting-started.md","filePath":"guide/getting-started.md","lastUpdated":1787732804000}`),a={name:`guide/getting-started.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to “Getting started”">​</a></h1><p>This walks from nothing to a working connector, with Claude as the example client — ChatGPT, Le Chat, Cursor and the rest work the same way and have their own notes on the <a href="/guide/client-compatibility">client compatibility</a> page. It assumes Docker and a reverse proxy that already terminates TLS for a hostname you control.</p><h2 id="what-you-need" tabindex="-1">What you need <a class="header-anchor" href="#what-you-need" aria-label="Permalink to “What you need”">​</a></h2><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>A host with Docker</td><td>any architecture — images are published for <code>linux/amd64</code> and <code>linux/arm64</code></td></tr><tr><td>A hostname with TLS</td><td>mcp-hub speaks plain HTTP; a reverse proxy in front terminates TLS</td></tr><tr><td><code>htpasswd</code></td><td>to hash the login password (<code>apache2-utils</code> / <code>httpd-tools</code>)</td></tr><tr><td>At least one MCP server</td><td>a stdio package, or a remote HTTP/SSE server you can reach</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Running without a container</p><p><code>npx @ni-c/mcp-hub</code> works too and is handy for a first look. The container is the recommended deployment because it carries the isolation, read-only root filesystem and resource limits the <a href="/guide/security">security model</a> assumes.</p><p>If all you want is the aggregate for a local, stdio-only client, none of this page applies: <code>npx @ni-c/mcp-hub --stdio</code> needs no hostname, no TLS and no password — see <a href="/guide/clients#local-clients-over-stdio">local clients</a>.</p></div><h2 id="_1-write-the-config" tabindex="-1">1. Write the config <a class="header-anchor" href="#_1-write-the-config" aria-label="Permalink to “1. Write the config”">​</a></h2><p>Create <code>config/mcp.json</code> — in a directory of its own, because the whole directory is mounted into the container (that is what keeps <a href="/guide/configuration#hot-reload">hot reload</a> working with editors that save via rename). It is exactly Claude Code&#39;s <code>mcpServers</code> block:</p><div class="language-json"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">{</span></span>
<span class="line"><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">  &quot;mcpServers&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: {</span></span>
<span class="line"><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">    &quot;paperless&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: {</span></span>
<span class="line"><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">      &quot;command&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: </span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">&quot;paperless-mcp&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">,</span></span>
<span class="line"><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">      &quot;args&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: [],</span></span>
<span class="line"><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">      &quot;env&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: {</span></span>
<span class="line"><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">        &quot;PAPERLESS_BASE_URL&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: </span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">&quot;http://paperless.example.net:8000&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">,</span></span>
<span class="line"><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">        &quot;PAPERLESS_API_TOKEN&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: </span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">&quot;\${PAPERLESS_API_TOKEN}&quot;</span></span>
<span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">      }</span></span>
<span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">    }</span></span>
<span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">  }</span></span>
<span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">}</span></span></code></pre></div><p><code>\${VAR}</code> is expanded from the container&#39;s environment, so no secret has to be written into the file. The <a href="/guide/configuration">configuration page</a> covers remote servers, <code>&quot;hub&quot;: false</code> and the naming rules.</p><h2 id="_2-hash-the-password" tabindex="-1">2. Hash the password <a class="header-anchor" href="#_2-hash-the-password" aria-label="Permalink to “2. Hash the password”">​</a></h2><p>There is one password. It guards the OAuth login, and through it every server the hub exposes.</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#953800;--shiki-dark:#FFA657;">htpasswd</span><span style="--shiki-light:#0550AE;--shiki-dark:#79C0FF;"> -bnBC</span><span style="--shiki-light:#0550AE;--shiki-dark:#79C0FF;"> 10</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> &quot;&quot;</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> &#39;yourpassword&#39;</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;"> |</span><span style="--shiki-light:#953800;--shiki-dark:#FFA657;"> tr</span><span style="--shiki-light:#0550AE;--shiki-dark:#79C0FF;"> -d</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> &#39;:\\n&#39;</span></span></code></pre></div><p>The output — a <code>$2y$10$…</code> string — goes into <code>PASSWORD_HASH</code>.</p><h2 id="_3-prepare-the-state-directory" tabindex="-1">3. Prepare the state directory <a class="header-anchor" href="#_3-prepare-the-state-directory" aria-label="Permalink to “3. Prepare the state directory”">​</a></h2><p><code>/data</code> holds the Ed25519 JWT key, the registered OAuth clients, their approvals and the refresh tokens. It <strong>must</strong> survive container recreates; losing it means every connector has to authorize again.</p><p>The container runs as the unprivileged <code>node</code> user (uid 1000), so a bind-mounted directory has to belong to that uid on the host:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#953800;--shiki-dark:#FFA657;">mkdir</span><span style="--shiki-light:#0550AE;--shiki-dark:#79C0FF;"> -p</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> data</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;"> &amp;&amp; </span><span style="--shiki-light:#953800;--shiki-dark:#FFA657;">sudo</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> chown</span><span style="--shiki-light:#0550AE;--shiki-dark:#79C0FF;"> -R</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> 1000:1000</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> data</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">A named volume does this for you</p><p><code>chown -R node:node /data</code> in the image only affects the image layer. A bind-mounted <code>./data</code> keeps the host&#39;s ownership, and the hub then cannot write <code>jwt-key.pem</code>. If you use a named Docker volume instead, it inherits the image&#39;s ownership and no <code>chown</code> is needed.</p></div><h2 id="_4-start-the-container" tabindex="-1">4. Start the container <a class="header-anchor" href="#_4-start-the-container" aria-label="Permalink to “4. Start the container”">​</a></h2><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#953800;--shiki-dark:#FFA657;">docker</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> run</span><span style="--shiki-light:#0550AE;--shiki-dark:#79C0FF;"> -d</span><span style="--shiki-light:#0550AE;--shiki-dark:#79C0FF;"> --name</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> mcp-hub</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;"> \\</span></span>
<span class="line"><span style="--shiki-light:#0550AE;--shiki-dark:#79C0FF;">  -p</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> 127.0.0.1:7690:80</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;"> \\</span></span>
<span class="line"><span style="--shiki-light:#0550AE;--shiki-dark:#79C0FF;">  -e</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> EXTERNAL_URL=&quot;https://mcp.example.net&quot;</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;"> \\</span></span>
<span class="line"><span style="--shiki-light:#0550AE;--shiki-dark:#79C0FF;">  -e</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> PASSWORD_HASH=&#39;$2y$10$…&#39;</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;"> \\</span></span>
<span class="line"><span style="--shiki-light:#0550AE;--shiki-dark:#79C0FF;">  -e</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> TRUSTED_PROXIES=&quot;192.168.1.0/24&quot;</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;"> \\</span></span>
<span class="line"><span style="--shiki-light:#0550AE;--shiki-dark:#79C0FF;">  -e</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> PAPERLESS_API_TOKEN=&quot;…&quot;</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;"> \\</span></span>
<span class="line"><span style="--shiki-light:#0550AE;--shiki-dark:#79C0FF;">  -v</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> &quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">$PWD</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">/config:/config:ro&quot;</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;"> \\</span></span>
<span class="line"><span style="--shiki-light:#0550AE;--shiki-dark:#79C0FF;">  -v</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> &quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">$PWD</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">/data:/data&quot;</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;"> \\</span></span>
<span class="line"><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">  ghcr.io/ni-c/mcp-hub:0.10.0</span></span></code></pre></div><p>Two of those matter more than the rest:</p><ul><li><strong><code>EXTERNAL_URL</code></strong> is the public HTTPS origin exactly as clients see it, with no trailing path. Every OAuth metadata document and every redirect is built from it.</li><li><strong><code>TRUSTED_PROXIES</code></strong> lists the addresses allowed to set <code>X-Forwarded-*</code>. Get it wrong and the login rate limiter counts the wrong IP — see <a href="/guide/security#trusted-proxies">Security</a>.</li></ul><p>Access tokens are bound to one endpoint out of the box — nothing to switch on. <code>RESOURCE_BOUND_TOKENS=false</code> exists only as a migration mode for deployments from 0.4 and earlier; see <a href="/guide/clients#resource-bound-tokens">Connecting clients</a>.</p><p>The full list lives in the <a href="/reference/environment">environment reference</a>. A Compose file with hardening options is on the <a href="/guide/deployment#docker-compose">deployment page</a>.</p><h2 id="_5-check-that-it-came-up" tabindex="-1">5. Check that it came up <a class="header-anchor" href="#_5-check-that-it-came-up" aria-label="Permalink to “5. Check that it came up”">​</a></h2><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#953800;--shiki-dark:#FFA657;">curl</span><span style="--shiki-light:#0550AE;--shiki-dark:#79C0FF;"> -fsS</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> http://127.0.0.1:7690/livez</span></span>
<span class="line"><span style="--shiki-light:#6E7781;--shiki-dark:#8B949E;"># {&quot;status&quot;:&quot;ok&quot;}</span></span></code></pre></div><p><code>/livez</code> is the only unauthenticated endpoint; it reports that the process is alive, nothing more. Per-server state is at <code>/health</code>, behind a bearer token.</p><p>Children are started in the background. If a server pulls a package at startup, its path answers <code>503</code> until it is ready — that is expected, not an error. <code>docker logs mcp-hub</code> shows each child&#39;s progress.</p><h2 id="_6-put-the-reverse-proxy-in-front" tabindex="-1">6. Put the reverse proxy in front <a class="header-anchor" href="#_6-put-the-reverse-proxy-in-front" aria-label="Permalink to “6. Put the reverse proxy in front”">​</a></h2><p>The proxy has to:</p><ul><li>terminate TLS for <code>mcp.example.net</code> and forward to <code>127.0.0.1:7690</code>,</li><li>pass <code>X-Forwarded-Proto</code> and <code>Host</code>,</li><li>allow streaming responses (turn response buffering <strong>off</strong>),</li><li>allow a request to run longer than 310 seconds — MCP tool calls are long,</li><li>cap request bodies at or below <code>MCP_BODY_LIMIT</code> (default 1 MB).</li></ul><p>Sample configurations for nginx and Caddy are on the <a href="/guide/deployment#reverse-proxy">deployment page</a>.</p><h2 id="_7-connect-a-client" tabindex="-1">7. Connect a client <a class="header-anchor" href="#_7-connect-a-client" aria-label="Permalink to “7. Connect a client”">​</a></h2><div class="vp-code-group"><div class="tabs"><input type="radio" name="group-172" id="tab-173" checked><label data-title="Claude Web" for="tab-173">Claude Web</label><input type="radio" name="group-172" id="tab-174"><label data-title="Claude Code" for="tab-174">Claude Code</label></div><div class="blocks"><div class="language-text active"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span>Settings → Connectors → Add custom connector</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  URL: https://mcp.example.net/hub</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Claude registers itself, sends you to the login page, and you enter the</span></span>
<span class="line"><span>password once. From then on it reconnects silently.</span></span></code></pre></div><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#953800;--shiki-dark:#FFA657;">claude</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> mcp</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> add</span><span style="--shiki-light:#0550AE;--shiki-dark:#79C0FF;"> -t</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> http</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> paperless</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> https://mcp.example.net/paperless/mcp</span></span></code></pre></div></div></div><p>Use <code>/hub</code> when you want one connector for everything, and <code>/&lt;name&gt;/mcp</code> for the servers you use constantly. Both can be registered side by side. The <a href="/guide/clients">clients page</a> explains the approval flow and what each client supports.</p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to “Next”">​</a></h2><ul><li><a href="/guide/configuration">Configuration</a> — remote servers, hiding servers from <code>/hub</code>, hot reload</li><li><a href="/guide/deployment">Deployment</a> — Compose, custom images, fail2ban, revoking clients</li><li><a href="/guide/faq">FAQ &amp; troubleshooting</a> — when something does not come up</li></ul>`,37)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};